package android.view;import android.content.Context;import java.util.*;public class ViewGroup extends View implements ViewParent {public static int adds,failAddAt;public static boolean throwRemoveAfter;public static Runnable onAdd,onRemove;public final List<View>children=new ArrayList<>();public ViewGroup(Context c){super(c);}public static class LayoutParams{public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}public int getChildCount(){return children.size();}public int indexOfChild(View v){return children.indexOf(v);}public View getChildAt(int i){return children.get(i);}public void addView(View v,int index){if(++adds==failAddAt)throw new IllegalStateException("add failed");if(v.parent!=null)throw new IllegalStateException("already parented");children.add(index,v);v.parent=this;v.attach(attached);if(onAdd!=null)onAdd.run();}public void removeView(View v){if(children.remove(v)){v.parent=null;v.attach(false);if(onRemove!=null)onRemove.run();if(throwRemoveAfter)throw new IllegalStateException("remove child after write");}}@Override public <T extends View>T findViewById(int id){T mine=super.findViewById(id);if(mine!=null)return mine;for(View v:children){T c=v.findViewById(id);if(c!=null)return c;}return null;}}
